import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if not node or node.get("kind") != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope):
    products_node = node_by_title(doc, f"{scope}: Products")
    if not products_node:
        return []
    rows = table_rows(products_node)
    entities_list = []
    for idx, row in rows:
        prod_id = row.get("product")
        if prod_id:
            entities_list.append({"id": prod_id, "description": prod_id})
    return entities_list

def recorded_end(doc, scope):
    max_day = 0.0
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                max_day = max(max_day, float(row["day"]))
            except (KeyError, ValueError):
                pass

    order_book_node = node_by_title(doc, f"{scope}: Order book")
    if order_book_node:
        for idx, row in table_rows(order_book_node):
            day_val = row.get("day") or row.get("day placed")
            if day_val:
                try:
                    max_day = max(max_day, float(day_val))
                except ValueError:
                    pass
    return max_day if max_day > 0 else None

def inputs(doc, scope):
    inputs_list = []

    # Products table: opening stock and kg per unit
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for idx, row in table_rows(prod_node):
            prod_id = row.get("product")
            if not prod_id: continue

            stock = row.get("opening stock")
            if stock:
                inputs_list.append({
                    "id": f"opening_stock_{prod_id}",
                    "time": 1.0,
                    "kind": "opening_stock",
                    "entities": [prod_id],
                    "fields": {"quantity": int(stock)},
                    "src": [[prod_node["node_id"], idx, ["product", "opening stock"]]]
                })

            weight = row.get("kg per unit")
            if weight:
                inputs_list.append({
                    "id": f"unit_weight_{prod_id}",
                    "time": 1.0,
                    "kind": "unit_weight",
                    "entities": [prod_id],
                    "fields": {"weight": float(weight)},
                    "src": [[prod_node["node_id"], idx, ["product", "kg per unit"]]]
                })

    # Daily ledger: produced, ordered
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                day = float(row["day"])
            except (KeyError, ValueError):
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            produced = row.get("produced")
            if produced and int(produced) > 0:
                inputs_list.append({
                    "id": f"prod_{prod_id}_{day}",
                    "time": day,
                    "kind": "production",
                    "entities": [prod_id],
                    "fields": {"quantity": int(produced)},
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "produced"]]]
                })

            ordered = row.get("ordered")
            if ordered and int(ordered) > 0:
                inputs_list.append({
                    "id": f"order_{prod_id}_{day}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod_id],
                    "fields": {"quantity": int(ordered)},
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "ordered"]]]
                })

    # Order book: planned production, planned orders
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        for idx, row in table_rows(ob_node):
            day_val = row.get("day") or row.get("day placed")
            if not day_val: continue
            try:
                day = float(day_val)
            except ValueError:
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            planned_prod = row.get("planned production")
            if planned_prod:
                inputs_list.append({
                    "id": f"planned_prod_{prod_id}_{day}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [prod_id],
                    "fields": {"quantity": int(planned_prod)},
                    "src": [[ob_node["node_id"], idx, ["day" if "day" in row else "day placed", "product", "planned production"]]]
                })

            # Handle two possible order book formats
            ordered = row.get("ordered") or row.get("units still open")
            if ordered:
                inputs_list.append({
                    "id": f"planned_order_{prod_id}_{day}",
                    "time": day,
                    "kind": "planned_order",
                    "entities": [prod_id],
                    "fields": {"quantity": int(ordered)},
                    "src": [[ob_node["node_id"], idx, ["day" if "day" in row else "day placed", "product", "ordered" if "ordered" in row else "units still open"]]]
                })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []

    # Daily ledger: shipped, backordered, stock
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                day = float(row["day"])
            except (KeyError, ValueError):
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            shipped = row.get("shipped")
            if shipped:
                outcomes_list.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [prod_id],
                    "value": int(shipped),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "shipped"]]]
                })

            backordered = row.get("backordered")
            if backordered:
                outcomes_list.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [prod_id],
                    "value": int(backordered),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "backordered"]]]
                })

            stock = row.get("stock")
            if stock:
                outcomes_list.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [prod_id],
                    "value": int(stock),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "stock"]]]
                })

    # Events list
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node and events_node.get("kind") == "list":
        all_entities = entities(doc, scope)
        for idx, line in enumerate(events_node.get("lines", [])):
            match = re.match(r"Day (\d+)", line)
            if match:
                day = float(match.group(1))
                involved = [e["id"] for e in all_entities if e["id"] in line]

                # Extract event kind from line
                kind = "event"
                if "dispatch capacity reached" in line: kind = "capacity_reached"
                elif "runs out of stock" in line: kind = "stock_out"
                elif "fully backordered" in line: kind = "fully_backordered"
                elif "backlog is cleared" in line: kind = "backlog_cleared"

                outcomes_list.append({
                    "time": day,
                    "kind": kind,
                    "entities": involved,
                    "value": None,
                    "src": [[events_node["node_id"], idx]]
                })

    return outcomes_list

def params(doc, scope):
    params_dict = {}
    scope_node = node_by_title(doc, scope)
    if scope_node and scope_node.get("kind") == "text":
        text = scope_node.get("text", "")
        match = re.search(r"Daily dispatch capacity: (\d+) kg", text)
        if match:
            params_dict["daily_dispatch_capacity"] = int(match.group(1))
    return params_dict


