import math

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the stock and dispatch process.
    """
    # Determine horizon
    if horizon is None:
        try:
            # recorded_end is provided as a helper function in the environment
            horizon = recorded_end(doc, scope)
        except (NameError, TypeError):
            pass

    if horizon is None:
        horizon = 0
        for inp in inputs:
            horizon = max(horizon, inp["time"])

    if start is None:
        start = 1.0

    daily_capacity = params.get("daily_dispatch_capacity", 0)

    # Data Organization
    opening_stocks = {}
    unit_weights = {}
    productions = {} # {day: {prod: qty}}
    orders_placed = {} # {day: {prod: qty}}
    all_products = set()

    for inp in inputs:
        kind = inp["kind"]
        time = inp["time"]
        entities = inp["entities"]
        fields = inp.get("fields", {})

        if not entities: continue
        prod = entities[0]
        all_products.add(prod)

        if kind == "opening_stock":
            opening_stocks[prod] = fields.get("quantity", 0)
        elif kind == "unit_weight":
            unit_weights[prod] = fields.get("weight", 0.0)
        elif kind in ("production", "planned_production"):
            qty = fields.get("quantity", 0)
            productions.setdefault(time, {})[prod] = productions.get(time, {}).get(prod, 0) + qty
        elif kind in ("order", "planned_order"):
            qty = fields.get("quantity", 0)
            orders_placed.setdefault(time, {})[prod] = orders_placed.get(time, {}).get(prod, 0) + qty

    # Simulation State
    stock = {prod: opening_stocks.get(prod, 0) for prod in all_products}
    order_queue = [] # list of {'prod': p, 'qty': q, 'day': d}
    is_stock_out_running = {prod: False for prod in all_products}
    prev_backordered = {prod: 0 for prod in all_products}

    all_outcomes = []

    # The document states days are numbered from day 1.
    for day in range(1, int(horizon) + 1):
        day_f = float(day)

        # 1. Production arrives
        day_prods = productions.get(day_f, {})
        for prod in all_products:
            stock[prod] += day_prods.get(prod, 0)

        # 2. Orders join the queue
        day_orders_dict = orders_placed.get(day_f, {})
        for prod, qty in day_orders_dict.items():
            if qty > 0:
                order_queue.append({'prod': prod, 'qty': qty, 'day': day_f})

        # 3. Dispatch
        remaining_capacity = daily_capacity
        # Queue priority: oldest first; then smaller remaining quantity; then lower product code.
        order_queue.sort(key=lambda x: (x['day'], x['qty'], x['prod']))

        shipped_today = {prod: 0 for prod in all_products}
        capacity_reached_today = False
        orders_shipped_anything = set() # store identity of orders that shipped something

        # Dispatch loop
        for order in order_queue:
            prod = order['prod']
            weight = unit_weights.get(prod, 0.0)

            # Units that can be shipped based on stock and order quantity
            possible_by_stock = min(order['qty'], stock[prod])
            if possible_by_stock <= 0:
                continue

            # Capacity limit
            if weight > 0:
                possible_by_capacity = math.floor(remaining_capacity / weight)
                shippable = min(possible_by_stock, possible_by_capacity)

                # Check if capacity was reached: "at least one order shipped fewer units than 
                # its product's stock would have allowed because the remaining capacity was too small"
                if shippable < possible_by_stock and possible_by_capacity < possible_by_stock:
                    capacity_reached_today = True

                remaining_capacity -= shippable * weight
            else:
                # Zero weight products don't consume capacity
                shippable = possible_by_stock

            # Update state
            order['qty'] -= shippable
            stock[prod] -= shippable
            shipped_today[prod] += shippable

            if shippable > 0:
                # Using (prod, day) to identify the order as only one per product per day is placed
                orders_shipped_anything.add((prod, order['day']))

        # Remove completed orders
        order_queue = [o for o in order_queue if o['qty'] > 0]

        # 4. Records and Events
        backordered_today = {prod: 0 for prod in all_products}
        for o in order_queue:
            backordered_today[o['prod']] += o['qty']

        day_outcomes = []

        # Product-specific outcomes
        for prod in sorted(all_products):
            day_outcomes.append({"time": day_f, "kind": "shipped", "entities": [prod], "value": shipped_today[prod]})
            day_outcomes.append({"time": day_f, "kind": "backordered", "entities": [prod], "value": backordered_today[prod]})
            day_outcomes.append({"time": day_f, "kind": "stock", "entities": [prod], "value": stock[prod]})

            # Backlog Cleared: "when its backordered units return to 0"
            if prev_backordered[prod] > 0 and backordered_today[prod] == 0:
                day_outcomes.append({"time": day_f, "kind": "backlog_cleared", "entities": [prod], "value": None})

            # Stock Out: "no stock while some of its units are backordered;... first day of each such run"
            if stock[prod] == 0 and backordered_today[prod] > 0:
                if not is_stock_out_running[prod]:
                    day_outcomes.append({"time": day_f, "kind": "stock_out", "entities": [prod], "value": None})
                    is_stock_out_running[prod] = True
            else:
                is_stock_out_running[prod] = False

        # Capacity reached outcome
        if capacity_reached_today:
            day_outcomes.append({"time": day_f, "kind": "capacity_reached", "entities": [], "value": None})

        # Fully backordered outcomes: "when nothing of it ships on the day it is placed"
        for prod, qty in day_orders_dict.items():
            if qty > 0 and (prod, day_f) not in orders_shipped_anything:
                day_outcomes.append({"time": day_f, "kind": "fully_backordered", "entities": [prod], "value": None})

        all_outcomes.extend(day_outcomes)
        prev_backordered = backordered_today.copy()

    # Filter outcomes after start
    return [o for o in all_outcomes if o["time"] > start]

