import math

def simulate(doc, scope, inputs, params, start=None, horizon=None) -> list:
    """
    A forward model of the stock and dispatch process.
    """
    # Determine horizon
    if horizon is None:
        try:
            # Using a local definition or checking the doc for recording end if helper is not available
            from __main__ import recorded_end
            horizon = recorded_end(doc, scope)
        except (ImportError, NameError):
            pass

    if horizon is None:
        horizon = 0
        for inp in inputs:
            horizon = max(horizon, inp["time"])

    if start is None:
        start = 1.0

    daily_capacity = params.get("daily_dispatch_capacity", 0)

    # Data Organization
    opening_stocks = {}
    unit_weights = {}
    productions = {} # {day: {prod: qty}}
    orders_placed = {} # {day: {prod: qty}}
    all_products = set()

    for inp in inputs:
        kind = inp["kind"]
        time = inp["time"]
        entities = inp["entities"]
        fields = inp.get("fields", {})

        if not entities: continue
        prod = entities[0]
        all_products.add(prod)

        if kind == "opening_stock":
            opening_stocks[prod] = fields.get("quantity", 0)
        elif kind == "unit_weight":
            unit_weights[prod] = fields.get("weight", 0.0)
        elif kind in ("production", "planned_production"):
            qty = fields.get("quantity", 0)
            productions.setdefault(time, {})[prod] = productions.get(time, {}).get(prod, 0) + qty
        elif kind in ("order", "planned_order"):
            qty = fields.get("quantity", 0)
            orders_placed.setdefault(time, {})[prod] = orders_placed.get(time, {}).get(prod, 0) + qty

    # Simulation State
    stock = {prod: opening_stocks.get(prod, 0) for prod in all_products}
    order_queue = [] # list of {'prod': p, 'qty': q, 'day': d}
    is_stock_out_running = {prod: False for prod in all_products}
    prev_backordered = {prod: 0 for prod in all_products}

    all_outcomes = []

    # The document states days are numbered from day 1.
    for day in range(1, int(horizon) + 1):
        day_f = float(day)

        # 1. Production arrives
        day_prods = productions.get(day_f, {})
        for prod in all_products:
            stock[prod] += day_prods.get(prod, 0)

        # 2. Orders join the queue
        day_orders_dict = orders_placed.get(day_f, {})
        for prod, qty in day_orders_dict.items():
            if qty > 0:
                order_queue.append({'prod': prod, 'qty': qty, 'day': day_f})

        # 3. Dispatch
        remaining_capacity = daily_capacity
        # Queue priority: oldest first; then smaller remaining quantity; then lower product code.
        order_queue.sort(key=lambda x: (x['day'], x['qty'], x['prod']))

        shipped_today = {prod: 0 for prod in all_products}
        capacity_reached_today = False
        orders_shipped_anything = set() # store identity of orders that shipped something

        # Dispatch loop
        for order in order_queue:
            prod = order['prod']
            weight = unit_weights.get(prod, 0.0)

            possible_by_stock = min(order['qty'], stock[prod])
            if possible_by_stock <= 0:
                continue

            if weight > 0:
                possible_by_capacity = math.floor(remaining_capacity / weight)
                shippable = min(possible_by_stock, possible_by_capacity)

                if shippable < possible_by_stock and possible_by_capacity < possible_by_stock:
                    capacity_reached_today = True

                remaining_capacity -= shippable * weight
            else:
                shippable = possible_by_stock

            order['qty'] -= shippable
            stock[prod] -= shippable
            shipped_today[prod] += shippable

            if shippable > 0:
                orders_shipped_anything.add((prod, order['day']))

        # Remove completed orders
        order_queue = [o for o in order_queue if o['qty'] > 0]

        # 4. Records and Events
        backordered_today = {prod: 0 for prod in all_products}
        for o in order_queue:
            backordered_today[o['prod']] += o['qty']

        day_outcomes = []

        # Product-specific outcomes
        for prod in sorted(all_products):
            day_outcomes.append({"time": day_f, "kind": "shipped", "entities": [prod], "value": shipped_today[prod]})
            day_outcomes.append({"time": day_f, "kind": "backordered", "entities": [prod], "value": backordered_today[prod]})
            day_outcomes.append({"time": day_f, "kind": "stock", "entities": [prod], "value": stock[prod]})

            if prev_backordered[prod] > 0 and backordered_today[prod] == 0:
                day_outcomes.append({"time": day_f, "kind": "backlog_cleared", "entities": [prod], "value": None})

            if stock[prod] == 0 and backordered_today[prod] > 0:
                if not is_stock_out_running[prod]:
                    day_outcomes.append({"time": day_f, "kind": "stock_out", "entities": [prod], "value": None})
                    is_stock_out_running[prod] = True
            else:
                is_stock_out_running[prod] = False

        if capacity_reached_today:
            day_outcomes.append({"time": day_f, "kind": "capacity_reached", "entities": [], "value": None})

        for prod, qty in day_orders_dict.items():
            if qty > 0 and (prod, day_f) not in orders_shipped_anything:
                day_outcomes.append({"time": day_f, "kind": "fully_backordered", "entities": [prod], "value": None})

        all_outcomes.extend(day_outcomes)
        prev_backordered = backordered_today.copy()

    return [o for o in all_outcomes if o["time"] > start]

import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def children(doc, node):
    return [node_by_id(doc, cid) for cid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return children(doc, node)

def table_rows(node):
    if not node or node.get("kind") != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope):
    products_node = node_by_title(doc, f"{scope}: Products")
    if not products_node:
        return []
    rows = table_rows(products_node)
    entities_list = []
    for idx, row in rows:
        prod_id = row.get("product")
        if prod_id:
            entities_list.append({"id": prod_id, "description": prod_id})
    return entities_list

def recorded_end(doc, scope):
    max_day = 0.0
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                max_day = max(max_day, float(row["day"]))
            except (KeyError, ValueError):
                pass

    order_book_node = node_by_title(doc, f"{scope}: Order book")
    if order_book_node:
        for idx, row in table_rows(order_book_node):
            day_val = row.get("day") or row.get("day placed")
            if day_val:
                try:
                    max_day = max(max_day, float(day_val))
                except ValueError:
                    pass
    return max_day if max_day > 0 else None

def inputs(doc, scope):
    inputs_list = []

    # Products table: opening stock and kg per unit
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for idx, row in table_rows(prod_node):
            prod_id = row.get("product")
            if not prod_id: continue

            stock = row.get("opening stock")
            if stock:
                inputs_list.append({
                    "id": f"opening_stock_{prod_id}",
                    "time": 1.0,
                    "kind": "opening_stock",
                    "entities": [prod_id],
                    "fields": {"quantity": int(stock)},
                    "src": [[prod_node["node_id"], idx, ["product", "opening stock"]]]
                })

            weight = row.get("kg per unit")
            if weight:
                inputs_list.append({
                    "id": f"unit_weight_{prod_id}",
                    "time": 1.0,
                    "kind": "unit_weight",
                    "entities": [prod_id],
                    "fields": {"weight": float(weight)},
                    "src": [[prod_node["node_id"], idx, ["product", "kg per unit"]]]
                })

    # Daily ledger: produced, ordered
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                day = float(row["day"])
            except (KeyError, ValueError):
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            produced = row.get("produced")
            if produced and int(produced) > 0:
                inputs_list.append({
                    "id": f"prod_{prod_id}_{day}",
                    "time": day,
                    "kind": "production",
                    "entities": [prod_id],
                    "fields": {"quantity": int(produced)},
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "produced"]]]
                })

            ordered = row.get("ordered")
            if ordered and int(ordered) > 0:
                inputs_list.append({
                    "id": f"order_{prod_id}_{day}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod_id],
                    "fields": {"quantity": int(ordered)},
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "ordered"]]]
                })

    # Order book: planned production, planned orders
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        for idx, row in table_rows(ob_node):
            day_val = row.get("day") or row.get("day placed")
            if not day_val: continue
            try:
                day = float(day_val)
            except ValueError:
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            planned_prod = row.get("planned production")
            if planned_prod:
                inputs_list.append({
                    "id": f"planned_prod_{prod_id}_{day}",
                    "time": day,
                    "kind": "planned_production",
                    "entities": [prod_id],
                    "fields": {"quantity": int(planned_prod)},
                    "src": [[ob_node["node_id"], idx, ["day" if "day" in row else "day placed", "product", "planned production"]]]
                })

            # Handle two possible order book formats
            ordered = row.get("ordered") or row.get("units still open")
            if ordered:
                inputs_list.append({
                    "id": f"planned_order_{prod_id}_{day}",
                    "time": day,
                    "kind": "planned_order",
                    "entities": [prod_id],
                    "fields": {"quantity": int(ordered)},
                    "src": [[ob_node["node_id"], idx, ["day" if "day" in row else "day placed", "product", "ordered" if "ordered" in row else "units still open"]]]
                })

    return inputs_list

def outcomes(doc, scope):
    outcomes_list = []

    # Daily ledger: shipped, backordered, stock
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            try:
                day = float(row["day"])
            except (KeyError, ValueError):
                continue
            prod_id = row.get("product")
            if not prod_id: continue

            shipped = row.get("shipped")
            if shipped:
                outcomes_list.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [prod_id],
                    "value": int(shipped),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "shipped"]]]
                })

            backordered = row.get("backordered")
            if backordered:
                outcomes_list.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [prod_id],
                    "value": int(backordered),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "backordered"]]]
                })

            stock = row.get("stock")
            if stock:
                outcomes_list.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [prod_id],
                    "value": int(stock),
                    "src": [[ledger_node["node_id"], idx, ["day", "product", "stock"]]]
                })

    # Events list
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node and events_node.get("kind") == "list":
        all_entities = entities(doc, scope)
        for idx, line in enumerate(events_node.get("lines", [])):
            match = re.match(r"Day (\d+)", line)
            if match:
                day = float(match.group(1))
                involved = [e["id"] for e in all_entities if e["id"] in line]

                # Extract event kind from line
                kind = "event"
                if "dispatch capacity reached" in line: kind = "capacity_reached"
                elif "runs out of stock" in line: kind = "stock_out"
                elif "fully backordered" in line: kind = "fully_backordered"
                elif "backlog is cleared" in line: kind = "backlog_cleared"

                outcomes_list.append({
                    "time": day,
                    "kind": kind,
                    "entities": involved,
                    "value": None,
                    "src": [[events_node["node_id"], idx]]
                })

    return outcomes_list

def params(doc, scope):
    params_dict = {}
    scope_node = node_by_title(doc, scope)
    if scope_node and scope_node.get("kind") == "text":
        text = scope_node.get("text", "")
        match = re.search(r"Daily dispatch capacity: (\d+) kg", text)
        if match:
            params_dict["daily_dispatch_capacity"] = int(match.group(1))
    return params_dict


